package com.benjamintaskis.createsignalextensions.client;
import com.benjamintaskis.createsignalextensions.network.OpenSpeedBoardConfigPayload; import com.benjamintaskis.createsignalextensions.network.SetSpeedBoardConfigPayload;
import net.minecraft.client.gui.GuiGraphics; import net.minecraft.client.gui.components.Button; import net.minecraft.client.gui.components.EditBox; import net.minecraft.client.gui.screens.Screen; import net.minecraft.network.chat.Component; import net.neoforged.neoforge.network.PacketDistributor;
public class SpeedBoardConfigScreen extends Screen {
 private final OpenSpeedBoardConfigPayload payload; private int left,top; private EditBox def,mu,high; private boolean muOverride,highOverride,turnoutMode; private Button done,mode;
 public SpeedBoardConfigScreen(OpenSpeedBoardConfigPayload p){super(Component.literal("Speed Board"));payload=p;muOverride=p.muOverridden();highOverride=p.highOverridden();turnoutMode=p.turnoutMode();}
 private EditBox field(int y,String name,int value){EditBox e=new EditBox(font,left+125,top+y,90,22,Component.literal(name));e.setMaxLength(3);e.setFilter(s->s.isEmpty()||s.matches("[0-9]{1,3}"));e.setValue(Integer.toString(value));addRenderableWidget(e);return e;}
 private Component modeLabel(){return Component.literal(turnoutMode?"Mode: Turnout (X)":"Mode: Normal");}
 @Override protected void init(){left=(width-290)/2;top=Math.max(10,(height-224)/2);mode=addRenderableWidget(Button.builder(modeLabel(),b->{turnoutMode=!turnoutMode;mode.setMessage(modeLabel());}).bounds(left+70,top+35,150,22).build());def=field(70,"Default",payload.defaultKmh()); if(payload.hasMu())mu=field(104,"Multiple Unit",payload.muKmh()); if(payload.hasHigh())high=field(payload.hasMu()?138:104,"High Speed",payload.highKmh()); done=addRenderableWidget(Button.builder(Component.literal("Done"),b->save()).bounds(left+105,top+187,80,22).build()); setInitialFocus(def);}
 private int val(EditBox e,int fallback){try{return Math.max(1,Math.min(999,Integer.parseInt(e.getValue())));}catch(Exception x){return fallback;}}
 @Override public boolean keyPressed(int key,int scan,int mods){if(mu!=null&&mu.isFocused())muOverride=true;if(high!=null&&high.isFocused())highOverride=true;return super.keyPressed(key,scan,mods);}
 @Override public boolean charTyped(char c,int mods){if(mu!=null&&mu.isFocused())muOverride=true;if(high!=null&&high.isFocused())highOverride=true;return super.charTyped(c,mods);}
 @Override public boolean mouseClicked(double x,double y,int button){ if(mu!=null && mu.isMouseOver(x,y))muOverride=true; if(high!=null && high.isMouseOver(x,y))highOverride=true; return super.mouseClicked(x,y,button); }
 private void syncInherited(){int d=val(def,payload.defaultKmh()); if(mu!=null&&!muOverride)mu.setValue(Integer.toString(d)); if(high!=null&&!highOverride)high.setValue(Integer.toString(d));}
 @Override public void tick(){super.tick();syncInherited();}
 private void save(){syncInherited();PacketDistributor.sendToServer(new SetSpeedBoardConfigPayload(payload.pos(),val(def,payload.defaultKmh()),mu==null?val(def,payload.defaultKmh()):val(mu,payload.muKmh()),high==null?val(def,payload.defaultKmh()):val(high,payload.highKmh()),muOverride,highOverride,turnoutMode));onClose();}
 @Override public void render(GuiGraphics g,int mx,int my,float pt){g.fill(0,0,width,height,0x78000000);g.fill(left,top,left+290,top+219,0xF0181818);g.fill(left+1,top+1,left+289,top+28,0xFF292925);g.drawCenteredString(font,title,width/2,top+10,0xFFF3F0E8);g.drawString(font,"Default",left+30,top+77,0xFFE5C72E);if(mu!=null)g.drawString(font,"Multiple Unit",left+30,top+111,0xFF6E9FE8);if(high!=null)g.drawString(font,"High Speed",left+30,top+(payload.hasMu()?145:111),0xFFF0F0F0);g.drawString(font,"km/h",left+222,top+77,0xFFAAA58F);mode.render(g,mx,my,pt);def.render(g,mx,my,pt);if(mu!=null)mu.render(g,mx,my,pt);if(high!=null)high.render(g,mx,my,pt);done.render(g,mx,my,pt);}
 @Override public boolean isPauseScreen(){return false;}
}
